			aIsInt = true
			aInt = n
		}
		if n, ok := bComp.(int); ok {
			bIsInt = true
			bInt = n
		}

		if aIsInt && bIsInt {
			if aInt != bInt {
				return aInt < bInt
			}
		} else if aIsInt != bIsInt {
			// Numbers come after strings
			return !aIsInt
		} else if aStr != bStr {
			return aStr < bStr
		}
	}

	return len(a.Path) < len(b.Path)
}

