// flatten transforms a JSON object into a list of statements
func flatten(root string, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		// Add the root object initialization
		statements = append(statements, Statement{
			Path:   []interface{}{},
			Value:  map[string]interface{}{},
			IsInit: true,
		})

		// Recursively flatten all keys
		for key, val := range v {
			stmts := flattenHelper([]interface{}{key}, val)
			statements = append(statements, stmts...)
		}

	case []interface{}:
		// Add the root array initialization
		statements = append(statements, Statement{
			Path:   []interface{}{},
			Value:  []interface{}{},
			IsInit: true,
		})

		// Recursively flatten all elements
		for i, val := range v {
			stmts := flattenHelper([]interface{}{i}, val)
			statements = append(statements, stmts...)
		}

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  []interface{}{},
			Value: v,
		})
	}

	return statements
}

func flattenHelper(path []interface{}, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		if len(v) == 0 {
			// Empty object
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		} else {
			// Non-empty object - emit initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})

			// Flatten each key
			for key, val := range v {
				newPath := append(append([]interface{}{}, path...), key)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case []interface{}:
		if len(v) == 0 {
			// Empty array
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})
		} else {
			// Non-empty array - emit initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})

			// Flatten each element
			for i, val := range v {
				newPath := append(append([]interface{}{}, path...), i)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  path,
			Value: v,
		})
	}

	return statements
}

