// flatten transforms a JSON object into a list of statements
func flatten(root string, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		// Add the root object initialization
		statements = append(statements, Statement{
			Path:   []interface{}{},
			Value:  map[string]interface{}{},
			IsInit: true,
		})

		// Recursively flatten all keys
		for key, val := range v {
			stmts := flattenHelper([]interface{}{key}, val)
			statements = append(statements, stmts...)
		}

	case []interface{}:
		// Add the root array initialization
		statements = append(statements, Statement{
			Path:   []interface{}{},
			Value:  []interface{}{},
			IsInit: true,
		})

		// Recursively flatten all elements
		for i, val := range v {
			stmts := flattenHelper([]interface{}{i}, val)
			statements = append(statements, stmts...)
		}

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  []interface{}{},
			Value: v,
		})
	}

	return statements
}

func flattenHelper(path []interface{}, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		if len(v) == 0 {
			// Empty object
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		} else {
			// Non-empty object - emit initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})

			// Flatten each key
			for key, val := range v {
				newPath := append(append([]interface{}{}, path...), key)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case []interface{}:
		if len(v) == 0 {
			// Empty array
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})
		} else {
			// Non-empty array - emit initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})

			// Flatten each element
			for i, val := range v {
				newPath := append(append([]interface{}{}, path...), i)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  path,
			Value: v,
		})
	}

	return statements
}

func statementToString(stmt Statement) string {
	pathStr := buildPathString(stmt.Path)
	valueStr := valueToString(stmt.Value)
	return fmt.Sprintf("%s = %s;", pathStr, valueStr)
}

func buildPathString(path []interface{}) string {
	if len(path) == 0 {
		return "json"
	}

	result := "json"
	for _, component := range path {
		switch v := component.(type) {
		case string:
			// Check if we need bracket notation
			if needsBracketNotation(v) {
				result += fmt.Sprintf("[%q]", v)
			} else {
				result += fmt.Sprintf(".%s", v)
			}
		case int:
			result += fmt.Sprintf("[%d]", v)
		case float64:
			result += fmt.Sprintf("[%d]", int(v))
		}
	}
	return result
}

func needsBracketNotation(key string) bool {
	if key == "" {
		return true
	}
	// Check if it's a valid identifier
	for i, ch := range key {
		if i == 0 {
			if !(ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch == '_') {
				return true
			}
		} else {
			if !(ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch >= '0' && ch <= '9' || ch == '_') {
				return true
			}
		}
	}
	return false
}

func valueToString(value interface{}) string {
	switch v := value.(type) {
	case string:
		data, _ := json.Marshal(v)
		return string(data)
	case float64:
		if v == float64(int64(v)) {
			return fmt.Sprintf("%d", int64(v))
		}
		return fmt.Sprintf("%v", v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	default:
		data, _ := json.Marshal(v)
		return string(data)
	}
}

func statementLess(a, b Statement) bool {
	// Compare paths lexicographically
	minLen := len(a.Path)
	if len(b.Path) < minLen {
		minLen = len(b.Path)
	}

	for i := 0; i < minLen; i++ {
		aComp := a.Path[i]
		bComp := b.Path[i]

		// Compare based on type
		aStr := fmt.Sprintf("%v", aComp)
		bStr := fmt.Sprintf("%v", bComp)

		// Try to compare as integers first
		aIsInt := false
		bIsInt := false
		aInt := 0
		bInt := 0

		if n, ok := aComp.(int); ok {
			aIsInt = true
			aInt = n
		}
		if n, ok := bComp.(int); ok {
			bIsInt = true
			bInt = n
		}

		if aIsInt && bIsInt {
			if aInt != bInt {
				return aInt < bInt
			}
		} else if aIsInt != bIsInt {
			// Numbers come after strings
			return !aIsInt
		} else if aStr != bStr {
			return aStr < bStr
		}
	}

	return len(a.Path) < len(b.Path)
}

func extractValue(line string) string {
	// Parse "path = value;" format
	parts := strings.SplitN(line, " = ", 2)
	if len(parts) != 2 {
		return ""
	}

	value := parts[1]
	if strings.HasSuffix(value, ";") {
		value = value[:len(value)-1]
	}

	// Skip assignments to {} or []
	if value == "{}" || value == "[]" {
		return ""
	}

	// If it's a quoted string, unquote it
	if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
		var unquoted string
		json.Unmarshal([]byte(value), &unquoted)
		return unquoted
	}

	return value
}

func parseStatement(line string) ([]interface{}, interface{}, error) {
	// Parse "path = value;" format
	parts := strings.SplitN(line, " = ", 2)
	if len(parts) != 2 {
		return nil, nil, fmt.Errorf("invalid statement format")
	}

	pathStr := parts[0]
	valueStr := parts[1]
	if strings.HasSuffix(valueStr, ";") {
		valueStr = valueStr[:len(valueStr)-1]
	}

	// Parse the path
	path := parsePath(pathStr)

	// Parse the value
	var value interface{}
	if valueStr == "null" {
		value = nil
	} else if valueStr == "true" {
		value = true
	} else if valueStr == "false" {
		value = false
	} else if valueStr == "{}" {
		value = map[string]interface{}{}
	} else if valueStr == "[]" {
		value = []interface{}{}
	} else if strings.HasPrefix(valueStr, "\"") && strings.HasSuffix(valueStr, "\"") {
		// String value
		if err := json.Unmarshal([]byte(valueStr), &value); err != nil {
			return nil, nil, err
		}
	} else if strings.HasPrefix(valueStr, "[") || strings.HasPrefix(valueStr, "{") {
		// JSON value
		if err := json.Unmarshal([]byte(valueStr), &value); err != nil {
			return nil, nil, err
		}
	} else {
		// Try to parse as number
		if err := json.Unmarshal([]byte(valueStr), &value); err != nil {
			return nil, nil, err
		}
	}

	return path, value, nil
}

func parsePath(pathStr string) []interface{} {
	if pathStr == "json" {
		return []interface{}{}
	}

	var path []interface{}
	pathStr = strings.TrimPrefix(pathStr, "json")

	// Parse path components
	i := 0
	for i < len(pathStr) {
		if pathStr[i] == '.' {
			// Property access
			i++
			j := i
			for j < len(pathStr) && pathStr[j] != '.' && pathStr[j] != '[' {
				j++
			}
			if j > i {
				path = append(path, pathStr[i:j])
			}
			i = j
		} else if pathStr[i] == '[' {
			// Array/bracket access
			j := i + 1
			for j < len(pathStr) && pathStr[j] != ']' {
				j++
			}
			if j > i+1 {
				component := pathStr[i+1 : j]
				// Try to parse as integer
				if n, err := stringToInt(component); err == nil {
					path = append(path, n)
				} else {
					// It's a string key, remove quotes if present
					if strings.HasPrefix(component, "\"") && strings.HasSuffix(component, "\"") {
						var key string
						json.Unmarshal([]byte(component), &key)
						path = append(path, key)
					} else {
						path = append(path, component)
					}
				}
			}
			i = j + 1
		} else {
			i++
		}
	}

	return path
}

func stringToInt(s string) (int, error) {
	var n int
	_, err := fmt.Sscanf(s, "%d", &n)
	return n, err
}

func convertPath(pathInterface interface{}) []interface{} {
	if arr, ok := pathInterface.([]interface{}); ok {
		return arr
	}
	return []interface{}{}
}

func buildStructure(statements []Statement) interface{} {
	// Determine if the root is an array or object
	if len(statements) == 0 {
		return nil
	}

	// Check the first statement
	if len(statements[0].Path) == 0 {
		// Root level
		if _, isArray := statements[0].Value.([]interface{}); isArray {
			// Root is array
			var arr []interface{}
			for _, stmt := range statements[1:] {
				if len(stmt.Path) > 0 {
					arr = setAtPath(arr, stmt.Path, stmt.Value).([]interface{})
				}
			}
			return arr
		} else {
			// Root is object
			obj := make(map[string]interface{})
			for _, stmt := range statements[1:] {
				if len(stmt.Path) > 0 {
					setAtPathInObject(obj, stmt.Path, stmt.Value)
				}
			}
			return obj
		}
	}

	return nil
}

func setAtPath(target interface{}, path []interface{}, value interface{}) interface{} {
	if len(path) == 0 {
		return value
	}

	switch p := path[0].(type) {
	case string:
		// Object key
		obj, ok := target.(map[string]interface{})
		if !ok {
			obj = make(map[string]interface{})
		}
		if len(path) == 1 {
			obj[p] = value
		} else {
			obj[p] = setAtPath(obj[p], path[1:], value)
		}
		return obj

	case float64:
		// Array index
		idx := int(p)
		arr, ok := target.([]interface{})
		if !ok {
			arr = []interface{}{}
		}
		// Extend array if needed
		for len(arr) <= idx {
			arr = append(arr, nil)
		}
		if len(path) == 1 {
			arr[idx] = value
		} else {
			arr[idx] = setAtPath(arr[idx], path[1:], value)
		}
		return arr

	case int:
		idx := p
		arr, ok := target.([]interface{})
		if !ok {
			arr = []interface{}{}
		}
		// Extend array if needed
		for len(arr) <= idx {
			arr = append(arr, nil)
		}
		if len(path) == 1 {
			arr[idx] = value
		} else {
			arr[idx] = setAtPath(arr[idx], path[1:], value)
		}
		return arr
	}

	return target
}

func setAtPathInObject(obj map[string]interface{}, path []interface{}, value interface{}) {
	if len(path) == 0 {
		return
	}

	if len(path) == 1 {
		// Last component
		switch p := path[0].(type) {
		case string:
			obj[p] = value
		}
		return
	}

	// Recursive case
	switch p := path[0].(type) {
	case string:
		if _, exists := obj[p]; !exists {
			// Determine what to create based on next component
			if _, ok := path[1].(int); ok {
				obj[p] = []interface{}{}
			} else {
				obj[p] = make(map[string]interface{})
			}
		}

		if subObj, ok := obj[p].(map[string]interface{}); ok {
			setAtPathInObject(subObj, path[1:], value)
		} else if subArr, ok := obj[p].([]interface{}); ok {
			obj[p] = setAtPath(subArr, path[1:], value)
		}
	}
}
