		// Explicit stdin
		input, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to read input: %v\n", err)
			os.Exit(ExitReadInput)
		}
	} else if strings.HasPrefix(args[0], "http://") || strings.HasPrefix(args[0], "https://") {
		// Fetch from URL
		resp, err := http.Get(args[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch URL: %v\n", err)
			os.Exit(ExitFetchURL)
		}
		defer resp.Body.Close()
		input, err = io.ReadAll(resp.Body)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to read response: %v\n", err)
			os.Exit(ExitReadInput)
		}
	} else {
		// Read from file
		input, err = os.ReadFile(args[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "open %s: %v\n", args[0], err)
			os.Exit(ExitOpenFile)
		}
	}

	if ungron {
		handleUngron(input)
	} else if values {
		handleValues(input)
	} else {
		handleGron(input)
	}
}

func handleGron(input []byte) {
	if jsonMode {
		handleGronJSON(input)
	} else {
		handleGronText(input)
	}
}

func handleGronText(input []byte) {
	var statements []Statement

	if stream {
		// Process each line as a separate JSON object
		scanner := bufio.NewScanner(strings.NewReader(string(input)))
		var jsonArray []interface{}

		for i := 0; scanner.Scan(); i++ {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}

			var obj interface{}
			decoder := json.NewDecoder(strings.NewReader(line))
			decoder.UseNumber()
			if err := decoder.Decode(&obj); err != nil {
				fmt.Fprintf(os.Stderr, "failed to form statements: %v\n", err)
				os.Exit(ExitFormStatements)
			}
			jsonArray = append(jsonArray, obj)
		}

		statements = flatten("json", jsonArray)
	} else {
		// Parse JSON preserving order
		var obj interface{}
		decoder := json.NewDecoder(bytes.NewReader(input))
		decoder.UseNumber()
		if err := decoder.Decode(&obj); err != nil {
			fmt.Fprintf(os.Stderr, "failed to form statements: %v\n", err)
			os.Exit(ExitFormStatements)
		}

		statements = flatten("json", obj)
	}

	// Sort if needed
	if !noSort {
		sort.Slice(statements, func(i, j int) bool {
			return statementLess(statements[i], statements[j])
		})
	}

	// Output
	for _, stmt := range statements {
		fmt.Println(statementToString(stmt))
	}
}

