				fmt.Fprintf(os.Stderr, "failed to parse statements: %v\n", err)
				os.Exit(ExitParseStatements)
			}

			if len(stmt) == 2 {
				path := convertPath(stmt[0])
				value := stmt[1]
				statements = append(statements, Statement{
					Path:  path,
					Value: value,
				})
			}
		}
	} else {
		// Parse text statements
		scanner := bufio.NewScanner(strings.NewReader(string(input)))
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}

			path, value, err := parseStatement(line)
			if err != nil {
				fmt.Fprintf(os.Stderr, "failed to parse statements: %v\n", err)
				os.Exit(ExitParseStatements)
			}

			statements = append(statements, Statement{
				Path:  path,
				Value: value,
			})
		}
	}

	// Build the original structure
	result := buildStructure(statements)

	// Encode to JSON
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to encode JSON: %v\n", err)
		os.Exit(ExitEncodeJSON)
	}
	fmt.Println(string(data))
}

// extractKeyOrder extracts the order of keys in a JSON object from the raw text
func extractKeyOrder(jsonStr string) map[string][]string {
	order := make(map[string][]string)
	// Simple regex to find all JSON object keys
	// This is a very rough approximation
	keyRegex := regexp.MustCompile(`"([^"]*)"[\s]*:`)
	matches := keyRegex.FindAllStringSubmatch(jsonStr, -1)
	for _, match := range matches {
		if len(match) > 1 {
			order[""] = append(order[""], match[1])
		}
	}
	return order
}

// reorderStatements attempts to reorder statements according to the extracted key order
func reorderStatements(statements []Statement, keyOrder map[string][]string) []Statement {
	// This is a simple implementation that tries to preserve some ordering
	// This is complex because we need to handle nested structures
	return statements
}

// flatten transforms a JSON object into a list of statements
func flatten(root string, obj interface{}) []Statement {
	return flattenHelper([]interface{}{}, obj)
}

func flattenWithOrder(root string, obj interface{}, rawJSON string, captureOrder bool) []Statement {
	return flattenHelper([]interface{}{}, obj)
}

// flattenHelper transforms a JSON object into a list of statements
func flattenHelper(path []interface{}, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		if len(path) == 0 {
			// Root object initialization
			statements = append(statements, Statement{
				Path:   []interface{}{},
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		} else {
			// Nested object initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		}

		if len(v) > 0 {
			// Flatten each key
			for key, val := range v {
				newPath := append(append([]interface{}{}, path...), key)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case []interface{}:
		if len(path) == 0 {
			// Root array initialization
			statements = append(statements, Statement{
				Path:   []interface{}{},
				Value:  []interface{}{},
				IsInit: true,
			})
		} else {
			// Nested array initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})
		}

		if len(v) > 0 {
			// Flatten each element
			for i, val := range v {
				newPath := append(append([]interface{}{}, path...), i)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case nil:
		statements = append(statements, Statement{
			Path:  path,
			Value: nil,
		})

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  path,
			Value: v,
		})
	}

	return statements
}

func statementToString(stmt Statement) string {
	pathStr := buildPathString(stmt.Path)
	valueStr := valueToString(stmt.Value)
	return fmt.Sprintf("%s = %s;", pathStr, valueStr)
