// flattenHelper transforms a JSON object into a list of statements
func flattenHelper(path []interface{}, obj interface{}) []Statement {
	var statements []Statement

	switch v := obj.(type) {
	case map[string]interface{}:
		if len(path) == 0 {
			// Root object initialization
			statements = append(statements, Statement{
				Path:   []interface{}{},
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		} else {
			// Nested object initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  map[string]interface{}{},
				IsInit: true,
			})
		}

		if len(v) > 0 {
			// Flatten each key
			for key, val := range v {
				newPath := append(append([]interface{}{}, path...), key)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case []interface{}:
		if len(path) == 0 {
			// Root array initialization
			statements = append(statements, Statement{
				Path:   []interface{}{},
				Value:  []interface{}{},
				IsInit: true,
			})
		} else {
			// Nested array initialization
			statements = append(statements, Statement{
				Path:   path,
				Value:  []interface{}{},
				IsInit: true,
			})
		}

		if len(v) > 0 {
			// Flatten each element
			for i, val := range v {
				newPath := append(append([]interface{}{}, path...), i)
				stmts := flattenHelper(newPath, val)
				statements = append(statements, stmts...)
			}
		}

	case nil:
		statements = append(statements, Statement{
			Path:  path,
			Value: nil,
		})

	default:
		// Scalar value
		statements = append(statements, Statement{
			Path:  path,
			Value: v,
